const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '单位换算表' },
      { kind: 'text', payload: '换算对象' },
      { kind: 'text', payload: '换算算式' },
      { kind: 'text', payload: '换算结果' },
      { kind: 'text', payload: '90 km/h' },
      { kind: 'text', payload: '90 ÷ 3.6' },
      { kind: 'text', payload: '25.0 m/s' },
      { kind: 'text', payload: '依据：1 m/s = 3.6 km/h；km/h 换算为 m/s 需除以 3.6；结果保留三位有效数字。' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var tableW = Math.min(W * 0.88, 760);
    var tableH = Math.min(H * 0.55, 360);
    var left = (W - tableW) / 2;
    var top = Math.max(70, (H - tableH) / 2 + 10);
    var titleY = Math.max(32, top - 34);
    var headerH = tableH * 0.24;
    var x0 = left;
    var x1 = left + tableW * 0.22;
    var x2 = left + tableW * 0.74;
    var x3 = left + tableW;
    var y0 = top;
    var y1 = top + headerH;
    var y2 = top + tableH;
    var c0 = (x0 + x1) / 2;
    var c1 = (x1 + x2) / 2;
    var c2 = (x2 + x3) / 2;
    var headerY = (y0 + y1) / 2;
    var dataY = (y1 + y2) / 2;
    var noteY = Math.min(H - 14, y2 + 28);
    var tableBg = ['M', x0, y0, 'L', x3, y0, 'L', x3, y2, 'L', x0, y2, 'Z'];
    var v1 = ['M', x1, y0, 'L', x1, y2];
    var v2 = ['M', x2, y0, 'L', x2, y2];
    var h1 = ['M', x0, y1, 'L', x3, y1];
    return {
      schemaVersion: 1,
      sceneId: 'unit-conversion-table',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'table-bg', commands: tableBg },
        { id: 'grid-v1', commands: v1 },
        { id: 'grid-v2', commands: v2 },
        { id: 'grid-h1', commands: h1 }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'table-bg', fill: '#FFFFFF', stroke: { width: 2 } },
          { type: 'path', pathId: 'grid-v1', fill: '#26354A', stroke: { width: 1.5 } },
          { type: 'path', pathId: 'grid-v2', fill: '#26354A', stroke: { width: 1.5 } },
          { type: 'path', pathId: 'grid-h1', fill: '#26354A', stroke: { width: 1.5 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: titleY }, hAlign: 'center', vAlign: 'middle', color: '#1F2937' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: c0, y: headerY }, hAlign: 'center', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: c1, y: headerY }, hAlign: 'center', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: c2, y: headerY }, hAlign: 'center', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: c0, y: dataY }, hAlign: 'center', vAlign: 'middle', color: '#1F2937' },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: c1, y: dataY }, hAlign: 'center', vAlign: 'middle', color: '#1F2937' },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: c2, y: dataY }, hAlign: 'center', vAlign: 'middle', color: '#1F2937' },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: left, y: noteY }, hAlign: 'left', vAlign: 'top', color: '#4B5563' }
        ]
      }
    };
  }
};
